{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol, which combines a polar chromanol head with an isoprenoid tail, has poor oral bioavailability in humans; this polar-head/long-lipophilic-tail architecture is the closest structural parallel to the query's quinone/polyprenyl structure and supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Lycopene, a large C40 polyisoprenoid, showed only about 1.2% systemic availability after oral dosing in humans, demonstrating that very large, highly lipophilic polyisoprenoids can have F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a smaller C40 polyisoprenoid hydrocarbon, showed 58.5% absolute bioavailability in humans, indicating that high lipophilicity alone does not always cause low F; however, its lower molecular weight and lack of a polar quinone head limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a prenylated polyphenol, has high oral bioavailability, but its much smaller size and different head group make it a weak counterexample for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is coenzyme Q10, a very large, highly lipophilic polyprenyl quinone. The closest transferable experimental evidence—tocotrienol (poor F) and lycopene (mostly low systemic availability)—supports F < 20%, while phytoene's high F is a weaker counterexample due to lower molecular weight and lack of the quinone head. Physicochemical liabilities (MW ~863, logP ~18, no ionizable groups) reinforce low oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself in the provided evidence.",
    "Lack of data on formulation, food effects, or dose for the query.",
    "High variability among polyisoprenoid analogues (phytoene high vs lycopene low) creates uncertainty in which analogue best represents CoQ10.",
    "No evidence on intestinal efflux or first-pass metabolism for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

